// ============================================
// VALIDATE INPUT
// ============================================

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// Extract project_id from header
const projectId = headers['x-project-id'] || headers['X-Project-ID'] || 'default';

// Required fields
const errors = [];

if (!body.guild_id) errors.push('guild_id');
if (!body.formation_id) errors.push('formation_id');
if (!body.formation_name) errors.push('formation_name');
if (!body.year_start) errors.push('year_start');
if (!body.year_end) errors.push('year_end');

// Validate year range
if (body.year_start && body.year_end && body.year_start >= body.year_end) {
  errors.push('year_start must be < year_end');
}

if (errors.length > 0) {
  return {
    valid: false,
    error: {
      code: 400,
      message: `Paramètres requis manquants ou invalides: ${errors.join(', ')}`,
      status: 'BAD_REQUEST'
    }
  };
}

return {
  valid: true,
  project_id: projectId,
  data: {
    guild_id: body.guild_id,
    formation_id: body.formation_id,
    formation_name: body.formation_name,
    formation_emoji: body.formation_emoji || '🎓',
    year_start: parseInt(body.year_start),
    year_end: parseInt(body.year_end),
    matieres: body.matieres || []
  }
};

