// ============================================
// CHECK API RESPONSE
// ============================================

const apiResponse = $input.first().json;
const inputData = $('Validate Input').first().json;

// Check for API error
if (apiResponse.error || apiResponse.statusCode >= 400) {
  return {
    success: false,
    error: {
      code: apiResponse.statusCode || 500,
      message: apiResponse.message || apiResponse.error || 'API error',
      status: 'API_ERROR'
    }
  };
}

// Success - extract promotion data
const promotion = apiResponse.data || apiResponse;

return {
  success: true,
  promotion: {
    id: promotion.id,
    formation_id: promotion.formation_id || inputData.data.formation_id,
    guild_id: inputData.data.guild_id,
    year_start: promotion.year_start || inputData.data.year_start,
    year_end: promotion.year_end || inputData.data.year_end,
    formation_name: inputData.data.formation_name,
    formation_emoji: inputData.data.formation_emoji,
    matieres: promotion.matieres || inputData.data.matieres
  },
  input_data: inputData.data
};

// ============================================
// PREPARE REDIS EVENT
// ============================================

const data = $input.first().json;
const promotion = data.promotion;

// Préparer l'event pour Redis Stream (format RFC-023)
const event = {
  event: 'promotion.created',
  guild_id: promotion.guild_id,
  timestamp: new Date().toISOString(),
  data: {
    promotion_id: promotion.id,
    formation_id: promotion.formation_id,
    formation_name: promotion.formation_name,
    formation_emoji: promotion.formation_emoji,
    year_start: promotion.year_start,
    year_end: promotion.year_end,
    matieres: promotion.matieres
  }
};

return {
  promotion: promotion,
  stream_name: 'formation:events:stream',
  event: event
};

// ============================================
// PREPARE SUCCESS RESPONSE
// ============================================

const data = $('Prepare Redis Event').first().json;

return {
  success: true,
  message: 'Promotion créée avec succès',
  promotion: data.promotion,
  event_published: true
};
